using System.ComponentModel;
using System.Net.Http.Json;
using ModelContextProtocol.Server;

namespace McpServer;

[McpServerToolType]
public static class ExternalApiTool
{
    [McpServerTool, Description("Fetches data from an external API for the given resource ID.")]
    public static async Task<string> FetchExternalData(
        IHttpClientFactory httpClientFactory,
        [Description("The resource identifier to look up")] string resourceId,
        CancellationToken cancellationToken = default)
    {
        var client = httpClientFactory.CreateClient("ExternalApi");

        var response = await client.GetAsync($"resources/{resourceId}", cancellationToken);
        response.EnsureSuccessStatusCode();

        var content = await response.Content.ReadAsStringAsync(cancellationToken);
        return content;
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpServer;

[McpServerPromptType]
public static class SummarizePrompt
{
    [McpServerPrompt, Description("Generates a prompt to summarize the provided text.")]
    public static IEnumerable<ChatMessage> Summarize(
        [Description("The text content to summarize")] string content,
        [Description("Desired summary style: brief, detailed, or bullet-points")] string style = "brief")
    {
        yield return new ChatMessage(
            ChatRole.User,
            $"""
            Please summarize the following text using a "{style}" style.

            Text:
            {content}
            """);
    }
}

